  let blend=studio_lod_weight(pixel,radius,side);
  let fine=orbit_sample(dir,radius,side,0,uv);
  let coarse=orbit_sample(dir,radius,max(1,(side-1)/4)+1,side*side,uv);
  let terrain=mix(fine,coarse,blend);
